def solve(inputs: dict) -> float:
    """Return the sum of entries of a square matrix power modulo the given modulus."""
    A = inputs.get("M", inputs.get("matrix", inputs.get("A")))
    exponent = inputs.get("exponent", inputs.get("power", inputs.get("n", inputs.get("exp"))))
    modulus = inputs.get("modulus", inputs.get("mod", inputs.get("m")))
    if A is None or exponent is None or modulus is None:
        raise KeyError("Expected matrix, exponent, and modulus")
    modulus, exponent = int(modulus), int(exponent)
    A = [[int(v) % modulus for v in row] for row in A]
    size = len(A)

    def multiply(X, Y):
        Z = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                xik = X[i][k]
                if xik:
                    for j in range(size):
                        Z[i][j] = (Z[i][j] + xik * Y[k][j]) % modulus
        return Z

    result = [[int(i == j) for j in range(size)] for i in range(size)]
    while exponent:
        if exponent & 1:
            result = multiply(result, A)
        A = multiply(A, A)
        exponent >>= 1
    return sum(map(sum, result))

