def solve(inputs: dict) -> float:
    """Iterate an affine linear congruential recurrence X=(aX+c) mod m."""
    def pick(*names):
        for name in names:
            if name in inputs:
                return inputs[name]
        raise KeyError(names[0])

    x = int(pick("X", "x", "s", "seed", "initial", "start"))
    a = int(pick("a", "multiplier", "coefficient"))
    c = int(pick("c", "increment", "addend", "b"))
    m = int(pick("m", "modulus", "mod"))
    rounds = int(pick("rounds", "steps", "iterations", "n", "times"))
    for _ in range(rounds):
        x = (a * x + c) % m
    return x

